{
  "world_updates": [
    {
      "type": "NPC_SPOKE"
    }
  ],
  "memory_summary": "The wanderer asks again how long the tribesman has lived here, and he answers with the same timeless reflection on the swamp's rhythms.",
  "new_entities": [],
  "rule_flags": [],
  "narration": "The tribesman leans back on the worn wooden post beside the hut, his gaze drifting toward the receding tide. He does not look at the wanderer directly, as if the question is not really about him but about the place itself.",
  "npc_response": "Longer than the reeds remember, wanderer. The swamp does not count years the way your world does. I have watched the same fire burn, the same spit turn, the same coconuts gather. Some days I forget my own name. Others, I remember the fever man who came with Leopold's shadow, and I wonder if he ever found his way back. But the hut has been here, and the fire has burned, and that is all the time I need."
}

{
  "world_updates": [
